export function structure(type,restored=false){
 const wall=restored?'#7c8060':'#596451',roof=restored?'#a4a47a':'#6e7860',dark='#303e30',light=restored?'#ead18b':'#25372d';
 const window=(x,y)=>`<rect x="${x}" y="${y}" width="8" height="10" fill="${light}" ${restored?'class="lamp"':''}/>`;
 const house=`<path d="M-33 5V-23L0-43 35-23V5L0 24Z" fill="${wall}"/><path d="M0-43 35-23 35 5 0 24Z" fill="${dark}"/><path d="M-43-24-9-50 41-29 7-4Z" fill="${roof}"/><path d="M-9-50 25-57 54-32 41-29Z" fill="#46543f"/><path d="M-33-19 0-3V24L-33 5Z" fill="${wall}"/>${window(-25,-10)}${window(-11,-3)}<path d="M8 6 19 0V14L8 20Z" fill="${light}"/>`;
 if(type==='home')return `<ellipse cy="26" rx="61" ry="17" fill="#101b15" opacity=".4"/><path d="M-60 14 0-15 65 17 2 47Z" fill="#556143" opacity=".45"/>${house}<path d="M18-47V-65L27-61V-42" fill="#78816b"/><path d="M-52 10V-4M-43 15V1M-58 1-37 12" stroke="#83876a" stroke-width="3"/>${restored?'<path d="M-49 29Q-27 14-7 30" fill="none" stroke="#b7a478" stroke-width="3"/><path d="M24-68Q8-85 23-98" fill="none" stroke="#bac4a0" opacity=".25" stroke-width="4"/>':''}`;
 if(type==='tower')return `<ellipse cy="29" rx="43" ry="12" fill="#101b15" opacity=".4"/><g stroke="#889176" stroke-width="4"><path d="M-16-40-27 29M17-40 28 29M-21-17 25 14M21-17-25 14M-23 9H24"/><path d="M-5-36-9 28M4-36 9 28" stroke-width="2"/></g><path d="M-25-42V-62L0-74 27-62V-42L0-30Z" fill="#768266"/><path d="M0-74 27-62V-42L0-30Z" fill="#41533f"/><path d="M-32-63 0-83 34-64 0-47Z" fill="#a0a181"/><path d="M-17-54-5-48V-38L-17-44Z" fill="${light}"/>`;
 if(type==='farm')return `<path d="M-68 16-15-9 64 27 12 54Z" fill="${restored?'#72804b':'#4b573b'}"/>${[0,1,2,3,4].map(i=>`<path d="M${-55+i*13} ${20+i*6}l41-21" stroke="${restored?'#b1b976':'#69734e'}" stroke-width="3"/>`).join('')}<g transform="translate(10,-14) scale(.8)">${house}</g>`;
 if(type==='fields')return `<path d="M-62 12 0-20 62 12 0 44Z" fill="#4b573b"/>${[0,1,2,3,4].map(i=>`<path d="M${-45+i*12} ${15+i*5}l40-22" stroke="#84935c" stroke-width="3"/><path d="M${-25+i*13} ${13+i*3}l-3-14m3 14 5-10" stroke="#a1a574" stroke-width="2"/>`).join('')}<path d="M-53 7V-15M-36 0V-22M-57-8-32-20" stroke="#8d8062" stroke-width="3"/>`;
 if(type==='bridge'){
  const planks=Array.from({length:11},(_,i)=>{const x=-55+i*10;if(!restored&&i>=4&&i<=6)return '';return `<path d="M${x} -17h9v34h-9Z" fill="${restored?['#bca273','#8f7954','#c4b487'][i%3]:'#737561'}" stroke="#3d4436" stroke-width="1"/>`;}).join('');
  return `<g transform="rotate(-12)"><path d="M-20-45H20V46H-20Z" fill="#294743"/><path d="M-61-13H-17M17-13H61M-61 13H-17M17 13H61" stroke="#444c3b" stroke-width="5"/>${planks}${restored?'<path d="M-26-12 25 13M-14-14 36 11" stroke="#dfc28c" stroke-width="4"/><path d="M-55-20H55M-55 20H55" stroke="#a18c65" stroke-width="3"/><path d="M-8-16H8V16H-8Z" fill="#6c7971" stroke="#b4beb0" stroke-width="1"/>':'<path d="M-17-17-8-12-18-4-10 5-17 17M17-17 10-7 19 0 11 10 17 17" fill="#737561" stroke="#adb18b" stroke-width="2"/><path d="M-55-20H-21L-10-10M55 20H22L12 31" fill="none" stroke="#92947a" stroke-width="3"/>'}<path d="M-50-25V25M50-25V25" stroke="#a7a080" stroke-width="3"/></g>`;
 }
 if(type==='scrap')return `<ellipse cy="20" rx="60" ry="18" fill="#152117"/><g transform="translate(-20,5)"><path d="M-25-5 10-23 33-12 0 7Z" fill="#8c8c6b"/><path d="M-25-5V12L0 25V7Z" fill="#59654d"/><path d="M0 7 33-12V6L0 25Z" fill="#3e503e"/><circle cx="-14" cy="14" r="7" fill="#1e2b23"/><circle cx="22" cy="12" r="7" fill="#1e2b23"/></g><path d="M12-23 29-33 50-23 33-13Z" fill="#8d775a"/><path d="M12-23V0L33 11V-13Z" fill="#70684f"/><path d="M33-13 50-23V0L33 11Z" fill="#4f5944"/><path d="M-30 35 0 19 20 31-10 47Z" fill="#676c51"/>`;
 if(type==='church')return `<g transform="translate(9,4)">${house}</g><path d="M-33 1V-59L-18-68-3-59V16Z" fill="#92947a"/><path d="M-18-68-3-59V16L-18 9Z" fill="#606f55"/><path d="M-38-59-18-94 2-59-18-49Z" fill="#69785c"/><path d="M-18-101V-87M-23-97H-13" stroke="#b4b897" stroke-width="2"/><path d="M-28-44V-32L-21-29V-41Z" fill="${light}"/>`;
 if(type==='radio')return `<ellipse cy="23" rx="53" ry="14" fill="#142117"/><g stroke="#98a385" fill="none"><path d="M-3-98-28 27M-3-98 23 27M-17-27 15 4M9-27-22 4M-22 4H19M-13-49 9-28M5-49-15-28" stroke-width="3"/><path d="M-3-106V-74M-24-75H18M-18-85H12" stroke-width="2"/></g><circle cx="-3" cy="-106" r="3" fill="${restored?'#ead18b':'#ac846b'}"/><g transform="translate(32,18) scale(.45)">${house}</g>`;
 return `<g transform="scale(1.15,.8)">${house}</g><path d="M-41 19 23 49 53 33-11 3Z" fill="#5c6851"/><path d="M-35 19 23 45" stroke="#adb18c" stroke-width="2"/>`;
}
let seed=17;
function random(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}
export function terrain(){
 seed=17;let trees='',contours='';
 for(let i=0;i<310;i++){
  const x=random()*1100,y=random()*760,size=7+random()*14;
  if((x>370&&x<555&&y>320&&y<470)||(x>610&&x<755)||(x<80)||(y<70))continue;
  trees+=`<g transform="translate(${x.toFixed(1)},${y.toFixed(1)})" opacity="${(.25+random()*.4).toFixed(2)}"><path d="M0 ${size}v${size*.3}" stroke="#46513b" stroke-width="2"/><path d="M0 ${-size} ${-size*.65} ${size*.65}H${size*.65}Z" fill="${['#41563b','#4c5e40','#3b5038'][i%3]}"/><path d="M0 ${-size*.5} ${-size*.8} ${size}H${size*.8}Z" fill="#3c5037"/></g>`;
 }
 for(let i=0;i<12;i++)contours+=`<path d="M${-160+i*13} ${150+i*25}C${100+i*8} ${-180+i*33} ${420+i*12} ${70+i*18} ${350+i*17} ${300+i*18}S${-30+i*22} ${580+i*21} ${170+i*20} 850" fill="none" stroke="#65704b" opacity=".13" stroke-width="1"/>`;
 return `<defs><pattern id="grid" width="85" height="85" patternUnits="userSpaceOnUse"><path d="M85 0H0V85" fill="none" stroke="#778269" stroke-width=".6" opacity=".09"/></pattern><filter id="paper"><feTurbulence type="fractalNoise" baseFrequency=".7" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".065"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter><radialGradient id="fog"><stop stop-color="#18251f" stop-opacity=".98"/><stop offset=".65" stop-color="#18251f" stop-opacity=".92"/><stop offset="1" stop-color="#18251f" stop-opacity="0"/></radialGradient></defs><rect width="1100" height="760" fill="#27352a"/><path d="M0 510Q170 380 390 470T850 620L1100 760H0Z" fill="#2d3a2a"/><path d="M0 0H570Q450 160 260 200T0 380Z" fill="#2b392b"/>${contours}<path d="M665-50C590 100 785 175 708 300S610 425 694 550 715 690 655 810" fill="none" stroke="#4b5b47" stroke-width="52"/><path d="M665-50C590 100 785 175 708 300S610 425 694 550 715 690 655 810" fill="none" stroke="#344e46" stroke-width="40"/><path d="M658-50C583 100 778 175 701 300S603 425 687 550 708 690 648 810" fill="none" stroke="#647667" stroke-width="1" opacity=".4"/>${trees}<path d="M120 730Q195 615 260 515T430 400Q560 374 670 350T1010 332" fill="none" stroke="#7f8060" stroke-width="10" opacity=".18"/><path d="M120 730Q195 615 260 515T430 400Q560 374 670 350T1010 332" fill="none" stroke="#8c8d65" stroke-width="1.5" stroke-dasharray="5 7" opacity=".5"/><path d="M430 400 300 255 460 205 620 205M430 400 490 590M670 350 825 230M670 350 850 490" fill="none" stroke="#a0a078" stroke-width="1.5" stroke-dasharray="3 8" opacity=".4"/><text class="map-name" x="100" y="375" transform="rotate(-26 100 375)">THE ALDER WOODS</text><text class="map-name" x="736" y="620" transform="rotate(70 736 620)">COLDWATER RIVER</text><text class="map-name" x="745" y="110" style="font-size:9px">EASTERN REACHES</text><rect width="1100" height="760" fill="url(#grid)"/><rect width="1100" height="760" fill="transparent" filter="url(#paper)" pointer-events="none"/>`;
}
